# -*- coding: utf-8 -*-
# pages_data_new_zzz_pricing_gaps.py — dedicated pages for treatments that were priced on /pricing/ but only had a
# "parent" page (Sep 24, 2026; see serenestaff/marketing/_seo/PRICING-PAGE-COVERAGE-2026-09-24.md).
# Identical file in both office repos. Hudson-voice copy; Barboursville's bv_localize rewrites place names.
# Prices come from build_pricing.py in each repo and are picked by SITE_LOC below — keep them in sync.
# Avoid the bare token "OH" in this file (the Barboursville localizer rewrites it to "WV").

# gen_pages.py defines SITE_LOC; seo_trim.py exec's this file without it, so fall back to the common.py catalogue
_BV = (globals().get("SITE_LOC") == "barboursville") if "SITE_LOC" in globals() else ("Barboursville" in globals().get("AREA_TOWNS", []))
def _p(hud, bv): return bv if _BV else hud
_BOTOX_UNIT = _p("$11", "$10")
_BABY = _p("$220", "$200")
_IV = _p("$149", "$99")
_OFFICE = "Serene Med Spa"

def _steps(a, b, c, d): return [("Consultation", a), ("Treatment", b), ("Results", c), ("Maintenance", d)]

_PRICE_NOTE = 'Prices are published and the consultation is complimentary. See the full <a href="/pricing/">price list</a>.'
def _price_block(eyebrow, h2, rows, note=""):
    cards = "".join(f'<div class="card reveal"><div class="ico">&#10022;</div><h3>{n}</h3><p><strong>{pr}</strong>{("<br>" + d) if d else ""}</p></div>' for n, pr, d in rows)
    note = note or _PRICE_NOTE
    return (f'<section id="pricing" class="tint-blush"><div class="wrap"><div class="section-head reveal"><div class="eyebrow">{eyebrow}</div><h2>{h2}</h2></div>'
            f'<div class="grid">{cards}</div>'
            f'<p class="rev-note" style="text-align:center;margin-top:18px">{note}</p></div></section>')

